window.ScripturaLexicons.BDAG_PART_0237 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-01\" data-source=\"BDAG\" data-search=\"Μισαήλ, ὁ nome próprio masculino Misael; jovem da fornalha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μισαήλ, ὁ</td><td>nome próprio masculino</td><td>Misael; jovem da fornalha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-02\" data-source=\"BDAG\" data-search=\"μισέω verbo odiar; detestar; desfavorecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μισέω</td><td>verbo</td><td>odiar; detestar; desfavorecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-03\" data-source=\"BDAG\" data-search=\"μισθαποδοσία, ας, ἡ substantivo feminino recompensa; retribuição; punição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μισθαποδοσία, ας, ἡ</td><td>substantivo feminino</td><td>recompensa; retribuição; punição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-04\" data-source=\"BDAG\" data-search=\"μισθαποδότης, ου, ὁ substantivo masculino recompensador; remunerador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μισθαποδότης, ου, ὁ</td><td>substantivo masculino</td><td>recompensador; remunerador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-05\" data-source=\"BDAG\" data-search=\"μίσθιος substantivo masculino diarista; empregado contratado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μίσθιος</td><td>substantivo masculino</td><td>diarista; empregado contratado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-06\" data-source=\"BDAG\" data-search=\"μισθός, οῦ, ὁ substantivo masculino salário; pagamento; recompensa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μισθός, οῦ, ὁ</td><td>substantivo masculino</td><td>salário; pagamento; recompensa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-07\" data-source=\"BDAG\" data-search=\"μισθόω verbo médio contratar; admitir trabalhadores BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μισθόω</td><td>verbo médio</td><td>contratar; admitir trabalhadores</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-08\" data-source=\"BDAG\" data-search=\"μίσθωμα, ατος, τό substantivo neutro aluguel; moradia alugada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μίσθωμα, ατος, τό</td><td>substantivo neutro</td><td>aluguel; moradia alugada</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-09\" data-source=\"BDAG\" data-search=\"μισθωτός substantivo masculino trabalhador contratado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μισθωτός</td><td>substantivo masculino</td><td>trabalhador contratado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-10\" data-source=\"BDAG\" data-search=\"μῖσος, ους, τό substantivo neutro ódio; animosidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μῖσος, ους, τό</td><td>substantivo neutro</td><td>ódio; animosidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-11\" data-source=\"BDAG\" data-search=\"μίτρα, ας, ἡ substantivo feminino faixa; turbante; cobertura da cabeça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μίτρα, ας, ἡ</td><td>substantivo feminino</td><td>faixa; turbante; cobertura da cabeça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-12\" data-source=\"BDAG\" data-search=\"Μιτυλήνη, ης, ἡ nome próprio feminino Mitilene; cidade da ilha de Lesbos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μιτυλήνη, ης, ἡ</td><td>nome próprio feminino</td><td>Mitilene; cidade da ilha de Lesbos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-13\" data-source=\"BDAG\" data-search=\"Μιχαήλ, ὁ nome próprio masculino Miguel; arcanjo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μιχαήλ, ὁ</td><td>nome próprio masculino</td><td>Miguel; arcanjo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-14\" data-source=\"BDAG\" data-search=\"μνᾶ, μνᾶς, ἡ substantivo feminino mina; unidade monetária BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνᾶ, μνᾶς, ἡ</td><td>substantivo feminino</td><td>mina; unidade monetária</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-15\" data-source=\"BDAG\" data-search=\"μνάομαι verbo médio cortejar; desposar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνάομαι</td><td>verbo médio</td><td>cortejar; desposar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-16\" data-source=\"BDAG\" data-search=\"Μνάσων, ωνος, ὁ nome próprio masculino Mnasom; cristão de Chipre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Μνάσων, ωνος, ὁ</td><td>nome próprio masculino</td><td>Mnasom; cristão de Chipre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-17\" data-source=\"BDAG\" data-search=\"μνεία, ας, ἡ substantivo feminino memória; menção em oração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνεία, ας, ἡ</td><td>substantivo feminino</td><td>memória; menção em oração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-18\" data-source=\"BDAG\" data-search=\"μνῆμα, ατος, τό substantivo neutro túmulo; sepultura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνῆμα, ατος, τό</td><td>substantivo neutro</td><td>túmulo; sepultura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-19\" data-source=\"BDAG\" data-search=\"μνημεῖον, ου, τό substantivo neutro monumento; sepultura; túmulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνημεῖον, ου, τό</td><td>substantivo neutro</td><td>monumento; sepultura; túmulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0237-20\" data-source=\"BDAG\" data-search=\"μνήμη, ης, ἡ substantivo feminino memória; lembrança; memorial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μνήμη, ης, ἡ</td><td>substantivo feminino</td><td>memória; lembrança; memorial</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0237-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μισαήλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μισαήλ</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">מִישָׁאֵל</span>; 1 Esdr 9:44. Em Jos. [Ant. 10, 188f], <span class=\"greek\">Μισάηλος</span>), Misael, um dos três jovens na fornalha ardente (Da 3:88; também 1:6f, 11, 19; 2:17; 1 Macc 2:59; 4 Macc 16:3, 21; 18:12) 1 Cl 45:7.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μισέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μισέω</span>, imperfeito <span class=\"greek\">ἐμίσουν</span>; futuro <span class=\"greek\">μισήσω</span>; 1º aoristo <span class=\"greek\">ἐμίσησα</span>; perfeito <span class=\"greek\">μεμίσηκα</span>. Passivo: futuro na 3ª pessoa singular <span class=\"greek\">μισηθήσεται</span> LXX; aoristo <span class=\"greek\">ἐμισήθην</span> (LXX; Joseph.); perfeito na 3ª pessoa singular <span class=\"greek\">μεμίσηται</span> (Jos., Bell. 3, 376); particípio <span class=\"greek\">μεμισημένος</span> (Hom.+; inscrições, papiros, embora bastante raro em ambos; LXX, Test12Patr, JosAs; ParJer 8:9; ApcSed 14 p. 136, 13 Ja.; AscIs 2:7; Philo, Joseph., Just., Tat., Ath.). Conforme o contexto, o significado deste verbo vai de “ter em desfavor” a “detestar”. O termo inglês “hate” geralmente sugere conotações afetivas que nem sempre fazem justiça, sobretudo, a alguns usos semíticos orientados pelas noções de honra e vergonha, <span class=\"greek\">μ</span>.=<span class=\"hebrew\" dir=\"rtl\">שָׂנֵא</span> (por exemplo, Dt 21:15, 16), no sentido de “ter em desfavor, estar pouco inclinado para, ter relativamente pouca consideração por”.</p><p class=\"entry-text\">① Sentir forte aversão por, odiar, detestar.</p><p class=\"entry-text\">ⓐ Com acusativo de pessoa (oposto a <span class=\"greek\">ἀγαπάω</span>, como em Dt 21:15, 16=Philo, Leg. All. 2, 48. Cf. AFridrichsen, SEÅ 5, ’40, 152–62) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:43</a> (PJoüon, RSR 20, 1930, 545f; MSmith, HTR 45, ’52, 71–73. Cf. a oração de Sólon [Fgm. 1, 5 Diehl3] <span class=\"greek\">γλυκὺν</span> <span class=\"greek\">φίλοισ</span>’, <span class=\"greek\">ἐχθροῖσι</span> <span class=\"greek\">πικρόν</span>; Pind., P. 2, 83f; Archilochus Lyr. Fgm. 66 Diehl3; 1QS 1:9f; <span class=\"greek\">μ</span>. <span class=\"greek\">τὸν</span> … <span class=\"greek\">ψευσμάτων</span> <span class=\"greek\">κακοσύνθετον</span> <span class=\"greek\">ποιητήν</span> Iren. 1, 15, 4 [Harv. I 152, 6] e ver ESutcliffe, Hatred at Qumran, Revue de Qumran 2, ’59/60, 345–55; KStendahl, HTR 55, ’62, 343–55; OLinton, StTh 18, ’64, 66–79; sobre o futuro como forma prescritiva, KMcKay, NovT 27, ’85, 219f; New Docs 4, 167, com referência a inscrição de Telmessos [II a.C.]: SEG XXIX, 1516, 4–6). 2 Cl 13:4; D 1:3; 2:7.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.71\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:71</a>; 6:22, 27; 19:14; J 7:7ab; 15:18f, 23f; 17:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:9</a>, 11; 3:13, 15; 4:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:16</a>; 19:11; Dg 2:6. <span class=\"greek\">ἀλλήλους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:3</a>; D 16:4. <span class=\"greek\">μ</span>. <span class=\"greek\">τινα</span> <span class=\"greek\">δωρεάν</span> (<span class=\"hebrew\" dir=\"rtl\">שָׂנֵא</span> <span class=\"hebrew\" dir=\"rtl\">חִנָּם</span>), odiar alguém sem motivo, injustificadamente (ver <span class=\"greek\">δωρεάν</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:25</a> (Ps 68:5.—34:19). <span class=\"greek\">μ</span>. <span class=\"greek\">τινα</span> <span class=\"greek\">ἀδίκως</span>, odiar alguém injustamente 1 Cl 60:3. De Deus: 1 Cl 30:6; Dg 9:2.</p><p class=\"entry-text\">ⓑ Com acusativo de coisa (Jos., Ant. 3, 274 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδικίαν</span>; Tat. 11, 1 <span class=\"greek\">πορνείαν</span>; Did., Gen. 175, 23 <span class=\"greek\">τ</span>. <span class=\"greek\">κακίαν</span>) <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:20</a>. <span class=\"greek\">ἀλήθειαν</span> 20:2; D 5:2. <span class=\"greek\">ἀνομίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:9</a> (Ps 44:8). <span class=\"greek\">τὴν</span> <span class=\"greek\">γαλῆν</span> 10:8. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐνθάδε</span>, coisas terrenas 2 Cl 6:6 (esta passagem também pode pertencer à acepção 2). <span class=\"greek\">τὴν</span> <span class=\"greek\">πονηρὰν</span> <span class=\"greek\">ἐπιθυμίαν</span> Hm 12, 1, 1. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Νικολαϊτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:6</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρᾶς</span> <span class=\"greek\">ὁδοῦ</span>, obras do mau caminho 4:10. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἡδυπαθείας</span> 2 Cl 17:7. <span class=\"greek\">παιδείαν</span> 1 Cl 35:8 (Ps 49:17). <span class=\"greek\">τὴν</span> <span class=\"greek\">πλάνην</span> 4:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">πονηρόν</span>19:11. <span class=\"greek\">σοφίαν</span> 1 Cl 57:5 (Pr 1:29). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">σάρκα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:29</a> (cf. Herm. Wr. 4, 6 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">μισήσῃς</span>, <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">φιλῆσαι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνασαι</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> Dg 6:5f. <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ὑπόκρισιν</span> 19:2b; D 4:12a. <span class=\"greek\">χιτῶνα</span> Jd 23. <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ἀρεστὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> 19:2a; D 4:12b (cf. ApcSed 14, 8 <span class=\"greek\">ἃ</span> <span class=\"greek\">μισεῖ</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">θεότης</span>). <span class=\"greek\">ὸ̔</span> <span class=\"greek\">μισῶ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ποιῶ</span>, faço aquilo que detesto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:15</a>.</p><p class=\"entry-text\">ⓒ Absolutamente IEph 14:2; IRo 8:3; Dg 5:17 (Just., A I, 57, 1; Tat. 17, 2; Ath. 31, 1).—Passivo: do cristianismo, <span class=\"greek\">ὅταν</span> <span class=\"greek\">μισῆται</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κόσμου</span>, sempre que é odiado pelo mundo IRo 3:3 (cf. Just., A I, 4, 5 <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">χρηστὸν</span> <span class=\"greek\">μισεῖσθαι</span> <span class=\"greek\">οὺ</span> <span class=\"greek\">δίκαιον</span>).—Particípio presente com presente na conjugação perifrástica, para exprimir a longa duração da atitude (Chariton 2, 6, 1 <span class=\"greek\">εἰμὶ</span> <span class=\"greek\">μισούμενος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἔρωτος</span>) <span class=\"greek\">ἔσεσθε</span> <span class=\"greek\">μισούμενοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:22</a>; 24:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:17</a> (cf. Herm. Wr. 9, 4b). <span class=\"greek\">μεμισημένος</span> (Iren. 1, 6, 3 [Harv. I 55, 14]), com <span class=\"greek\">ἀκάθαρτος</span>, impuro e repulsivo (por motivos cultuais), de aves <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:2</a>.</p><p class=\"entry-text\">② Estar pouco inclinado para, desfavorecer, desconsiderar, em contraste com o tratamento preferencial (Gn 29:31; Dt 21:15, 16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:13</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:25</a> ou <span class=\"greek\">ἑαυτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:26</a> (cf. a formulação de Plut, Mor. 556d <span class=\"greek\">οὐδ</span>’ <span class=\"greek\">ἐμίσουν</span> <span class=\"greek\">ἑαυτούς</span>; sobre o tema, cf. Tyrtaeus [VII a.C.] 8, 5 D.3). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:13</a> (Mal 1:2f). Talvez 2 Cl 6:6 (ver 1b). (JDenney, The Word ‘Hate’ in Lk 14:26: ET 21, 1910, 41f; WBleibtreu, Paradoxe Aussprüche Jesu: Theol. Arbeiten aus d. wissensch. Prediger-Verein d. Rheinprovinz, nova série 20, 24, 15–35; RSockman, The Paradoxes of J. ’36).—ACarr, The Mng. of ‘Hatred’ in the NT: Exp. 6th ser., 12, 1905, 153–60.—DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μισθαποδοσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μισθαποδοσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μισθός</span>, <span class=\"greek\">ἀποδίδωμι</span>, ver entrada seguinte; somente em Hb e na literatura eclesiástica. Mas <span class=\"greek\">ἀποδίδωμι</span> [ver esse verbete 2a] <span class=\"greek\">τὸν</span> <span class=\"greek\">μισθόν</span> é bastante comum), retribuição, favorável ou desfavorável, literalmente “pagamento de salário”.</p><p class=\"entry-text\">ⓐ Em sentido favorável: <span class=\"greek\">ἀποβλέπειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μ</span>., aguardar uma recompensa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:26</a>; da confiança, <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">μεγάλην</span> <span class=\"greek\">μ</span>. 10:35.</p><p class=\"entry-text\">ⓑ Em sentido desfavorável: punição, retribuição, <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">ἔνδικον</span> <span class=\"greek\">μ</span>., receber justa penalidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:2</a>.—DELG s.v. <span class=\"greek\">δίδωμι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μισθαποδότης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μισθαποδότης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">μισθός</span> + <span class=\"greek\">ἀποδότης</span>, “aquele que paga salários”, ver entrada anterior; somente em Hb e na literatura eclesiástica), remunerador, recompensador, literalmente “pagador de salários”; de Deus (AcThom 142 [Aa II/2, 249, 10]; 159 [ibid. 271, 1b]; PGen [Christian] 14:27) <span class=\"greek\">τῷ</span> <span class=\"greek\">μισθαποδότῃ</span> <span class=\"greek\">θεῷ</span>) <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐκζητοῦσιν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">γίνεται</span>, (Deus) mostra-se recompensador dos que o procuram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:6</a>.—New Docs 3, 76; DELG s.v. <span class=\"greek\">δίδωμι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίσθιος</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μίσθιος</span> (a rigor, adjetivo de duas ou três terminações. Em nossa literatura, apenas substantivado: TestSol [neutro]; ApcEsdr 1:14 p. 25, 7 Tdf.; Jos., Bell. 5, 49; Plut., Lyc. 50 [16, 7] e outros; Anth. Pal. 6, 283, 3; PAmh 92, 19; Lev 25:50; Job 7:1; Tob 5:12 BA; Sir 7:20), <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, diarista, trabalhador contratado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:17</a>, 19, 21 variante de leitura (Alciphron 2, 32, 3 <span class=\"greek\">δέχου</span> <span class=\"greek\">με</span> <span class=\"greek\">μισθωτὸν</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἀγρόν</span>, <span class=\"greek\">πάντα</span> <span class=\"greek\">ὑπομένειν</span> <span class=\"greek\">ἀνεχόμενον</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀπλήρωτον</span> <span class=\"greek\">ἐμπλῆσαι</span> <span class=\"greek\">γαστέρα</span> = contrata-me como trabalhador rural, disposto a suportar tudo apenas para encher minha barriga insaciável).—Frisk s.v. <span class=\"greek\">μισθός</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μισθός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μισθός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Hom.+).</p><p class=\"entry-text\">① Remuneração pelo trabalho realizado, pagamento, salário <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:18</a>. Personificado: <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀφυστερημένος</span> <span class=\"greek\">κράζει</span>, o salário que retivestes clama (aos céus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:4</a> (cf. TestJob 12:4). <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀποδιδόναι</span>, pagar salário (ver <span class=\"greek\">ἀποδίδωμι</span> 2a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:8</a> (cf. Iren. 4, 36, 7 [Harv. II 284, 3]; 1, 4, 3 [Harv. I, 36, 11) <span class=\"greek\">μισθὸν</span> <span class=\"greek\">λαμβάνειν</span>, receber salário (Diod S 12, 53, 2; Jos., Bell. 2, 296, Ant. 4, 206) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:36</a>. <span class=\"greek\">μισθοὺς</span> <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τινός</span>, receber pagamento(s) por alguma coisa Hm 11:12 (<span class=\"greek\">μ</span>. <span class=\"greek\">λαμβ</span>. <span class=\"greek\">τινός</span> como em Philo, Spec. Leg. 4, 98; para o plural, cf. Aesop 87d, 12 Ch.; Jos., Ant. 1, 183; BGU 1067, 15 [II d.C.]; Just., A I, 27, 2). <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀδικίας</span>, dinheiro pago pela traição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:18</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἀδικίας</span>, lucro desonesto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:15</a>; sobre <span class=\"greek\">ἀδικούμενοι</span> <span class=\"greek\">μισθὸν</span> <span class=\"greek\">ἀδικίας</span>, versículo 13, ver <span class=\"greek\">ἀδικέω</span> 2.—Em <span class=\"greek\">τῇ</span> <span class=\"greek\">πλάνῃ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Βαλαὰμ</span> <span class=\"greek\">μισθοῦ</span> <span class=\"greek\">ἐξεχύθησαν</span>, <span class=\"greek\">μισθοῦ</span> é genitivo de preço (como no fragmento cômico anônimo 218 Kock; Diod S 4, 20, 2; 3 <span class=\"greek\">μισθοῦ</span> <span class=\"greek\">ἐργάζεσθαι</span>; Tat. 1, 3 <span class=\"greek\">μισθοῦ</span> <span class=\"greek\">πιπράκοντας</span>; 18, 3; <span class=\"greek\">μισθοῦ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">οἰκείοις</span> <span class=\"greek\">ἀποκαθιστᾶν</span>), por pagamento ou lucro Jd 11 (ver <span class=\"greek\">ἐκχέω</span> 3).</p><p class=\"entry-text\">② Reconhecimento (sobretudo de Deus) pela qualidade moral de uma ação, recompensa, sentido transferido de 1 (Pla., Rep. 10, 614a <span class=\"greek\">τῷ</span> <span class=\"greek\">δικαίῳ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">μισθοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δῶρα</span> <span class=\"greek\">γίγνεται</span>; cf. 2, 363d <span class=\"greek\">ἡγησάμενοι</span> <span class=\"greek\">κάλλιστον</span> <span class=\"greek\">ἀρετῆς</span> <span class=\"greek\">μισθὸν</span> <span class=\"greek\">μέθην</span> <span class=\"greek\">αἰώνιον</span>, “considerando a melhor recompensa da virtude uma bebedeira eterna”; Plut., Mor. 183d; Lucian, Vit. Auct. 24; Jos., Ant. 1, 183; 18, 309; LXX; Did., Gen. 20, 6).</p><p class=\"entry-text\">ⓐ Em reconhecimento de conduta louvável, recompensa 2 Cl 3:3. <span class=\"greek\">μισθὸν</span> <span class=\"greek\">ἔχειν</span>, ter recompensa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:46</a>; 6:1 (cf. habeo pretium: Horace, Ep. 1, 16, 47). <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπέχειν</span>, ter recebido integralmente a recompensa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:2</a>, 5, 16 (ver <span class=\"greek\">ἀπέχω</span> 1). <span class=\"greek\">μισθὸν</span> <span class=\"greek\">λαμβάνειν</span>, receber a recompensa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:8</a>, 14; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:41a</a> (Jos., Ant. 6, 48 <span class=\"greek\">μὴ</span> <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">προφήτην</span> <span class=\"greek\">μισθόν</span>), versículo 41b; GJs 20:2 (códices); AcPlCor 2:36. Também <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπολαμβάνειν</span> 2 Cl 9:5; Hs 5, 6, 7b (GrBar 15:3; ApcEsdr 1:14 p. 25:9 Tdf.). <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">κομίσασθαι</span> 2 Cl 11:5 (Theoph. Ant 2, 27 [p. 164, 19]). <span class=\"greek\">μισθὸν</span> <span class=\"greek\">πλήρη</span> <span class=\"greek\">ἀπολαμβάνειν</span>, receber recompensa plena 2J 8. <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀποδιδόναι</span>, pagar a recompensa (Wsd 10:17) 2 Cl 20:4; cf. 11:8. <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἀνταποδότης</span> 19:11; D 4:7 (cf. <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀνταποδόσεως</span> TestJob 14:4). <span class=\"greek\">τὸν</span> <span class=\"greek\">μισθὸν</span> <span class=\"greek\">εὑρεῖν</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, encontrar a recompensa junto de Deus Hs 2:5 (<span class=\"greek\">μ</span>. <span class=\"greek\">εὑρ</span>. como em Ezk 27:33). <span class=\"greek\">μισθὸν</span> <span class=\"greek\">αἰτεῖν</span>, pedir como recompensa 2 Cl 19:1. <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">πολὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οὐρανοῖς</span>, grande é a recompensa nos céus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:12</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:23</a>, 35. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">μικρός</span> 2 Cl 15:1. Vinda com a parúsia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:18</a>; 21:3. Com genitivo objetivo (<span class=\"greek\">μ</span>. <span class=\"greek\">ἀρετῆς</span>, Did., Gen. 174, 8) <span class=\"greek\">μ</span>. <span class=\"greek\">δικαιοσύνης</span>, recompensa pela justiça 20:2; D 5:2. <span class=\"greek\">διδόναι</span> <span class=\"greek\">μισθὸν</span> <span class=\"greek\">ἀντιμισθίας</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἐλάβομεν</span>, dar retribuição pelo que recebemos 2 Cl 1:5 (<span class=\"greek\">δίδ</span>. <span class=\"greek\">μ</span>. como em Ael. Aristid. 28, 10 K.=49 p. 494 D.; Sir 51:30). <span class=\"greek\">ἀπολέσαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μ</span>., perder a recompensa (Jos., Ant. 1, 183a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:41</a>; Hs 5, 6, 7a; <span class=\"greek\">ἔσται</span> <span class=\"greek\">μοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., trar-me-á recompensa 1:5.—<span class=\"greek\">τῷ</span> <span class=\"greek\">ἐργαζομένῳ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">οὐ</span> <span class=\"greek\">λογίζεται</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">χάριν</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">ὀφείλημα</span>, os salários concedidos a quem trabalha não são considerados favor, mas algo devido à pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:4</a>.</p><p class=\"entry-text\">ⓑ Em sentido desfavorável, a retribuição que consiste em punição (trágicos; Hdt. 8, 116f; Callim., Hymn. in Dian. 263; Dionys. Hal. 10, 51; 2 Macc 8:33) <span class=\"greek\">ὁ</span> <span class=\"greek\">μισθὸς</span> <span class=\"greek\">αὐτῆς</span> (subentendido <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀδικίας</span>) <span class=\"greek\">κόλασις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θάνατος</span> Dg 9:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρίας</span> <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">αὐτοῦ</span>, a recompensa da maldade está reservada para ele 4:12.</p><p class=\"entry-text\">ⓒ Recompensa ou punição, conforme o caso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:12</a>; 1 Cl 34:3 (ambos Is 40:10); 21:3.—Billerb. IV 1245f (índice); especialmente IV 487–500: Altsynagog. Lohnlehre; KWeiss, D. Frohbotsch. Jesu über Lohn u. Vollkommenheit (Mt 20:1–16) 1927; MWagner, D. Lohnged. im Ev.: NKZ 43, ’32, 106–12; 129–39; OMichel, D. Lohnged. in d. Verkünd. Jesu: ZST 9, ’32, 47–54.—GWetter, D. Vergeltungsged. b. Pls 1912; FFilson, St. Paul’s Conception of Recompense ’32; HHeidland, D. Anrechng. des Glaubens z. Gerechtigkeit ’36; GBornkamm, D. Lohnged. im NT: EvTh ’44, 143–66; BReicke, The NT Conception of Reward: MGoguel Festschr. ’50, 195–206; MSmith, Tannaitic Par. to the Gosp. ’51, 49–73; WPesch, Der Lohngedanke in d. Lehre Jesu usw., tese de Munique ’55 (bibliografia); GdeRu, NovT 8, ’66, 202–22.—B. 814. DELG. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μισθόω</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μισθόω</span> (<span class=\"greek\">μισθός</span>; em nossa literatura [Mt] e na LXX, apenas na voz média); 1º aoristo <span class=\"greek\">ἐμισθωσάμην</span>; perfeito <span class=\"greek\">μεμίσθωμαι</span> LXX; a voz média tem o sentido de contratar, admitir para si (Hdt. e outros; inscrições, papiros, LXX), com acusativo: <span class=\"greek\">ἐργάτας</span> (111, 11; Jos., Bell. 3, 437, Ant. 11, 174) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:1</a> (quanto a <span class=\"greek\">μ</span>. <span class=\"greek\">εἰς</span>, cf. Appian, Mithrid. 23 §90 <span class=\"greek\">ἐς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ἐμισθώσαντο</span>), 7.—Diod S 4, 20, 3 <span class=\"greek\">ὁ</span> <span class=\"greek\">μισθωσάμενος</span> <span class=\"greek\">ἐλεήσας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μισθὸν</span> <span class=\"greek\">ἀποδοὺς</span> <span class=\"greek\">ἀπέλυσε</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἔργων</span> = o empregador teve compaixão de uma mulher que acabara de dar à luz, pagou-lhe integralmente o salário e dispensou-a antecipadamente do trabalho. Apenas sua bondade o leva a conceder esse favor; ver também Strabo 3, 4, 17.—New Docs 2, 91. DELG s.v. <span class=\"greek\">μισθός</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίσθωμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μίσθωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">μισθόω</span>). O sentido usual na voz ativa, “valor contratual, aluguel” (Hdt. e outros; inscrições, LXX; Philo, Spec. Leg. 1, 280), não aparece em nossa literatura (Ac); e o sentido passivo, aquilo que se aluga, casa alugada, não se encontra fora dela (até Ammonius Gramm. [100 d.C.] p. 93 Valck. nada sabe desse uso. Por isso merece atenção a tradução “às suas próprias custas” [NRSV]): <span class=\"greek\">ἐν</span> <span class=\"greek\">ἰδίῳ</span> <span class=\"greek\">μισθώματι</span>, em seu próprio alojamento alugado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:30</a> (quanto à ideia, cf. Jos., Ant. 18, 235).—HCadbury, JBL 45, 1926, 321f.—Sobre arrendamento, ver New Docs 2, 91 (<span class=\"greek\">μισθόω</span>). DELG s.v. <span class=\"greek\">μισθός</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μισθωτός</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μισθωτός</span> (<span class=\"greek\">μισθόω</span>; propriamente adjetivo de três terminações. Em nossa literatura, somente como substantivo: Aristoph. e outros; inscrições, papiros, LXX; TestJob 12:4; Philo, Spec. Leg. 2, 82; 83; Jos., Bell. 1, 517), <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span>, empregado contratado, de pescadores assalariados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:20</a>. De pastores assalariados J 10:12f (<span class=\"greek\">μ</span>. como inferior: Ael. Aristid. 46 p. 206 D.; Hippocr., Ep. 16, 3; Themist. I p. 10f <span class=\"greek\">μ</span>. <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">βουκόλου</span>; Plut., Mor. 37e <span class=\"greek\">μ</span>. contrasta com o <span class=\"greek\">θεῖος</span> <span class=\"greek\">ἡγεμών</span>, o <span class=\"greek\">λόγος</span>).—DELG s.v. <span class=\"greek\">μισθός</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μῖσος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μῖσος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Aeschyl. e outros; Vett. Val. 242, 25; POslo 15, 14 [II d.C.] texto mágico; LXX; Test12Patr; Jos., Bell. 5, 556; Just., D. 14, 2), ódio: <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">στραφήσεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., o afeto se transformará em animosidade D 16:3. Personificado Hs 9, 15, 3. Ver <span class=\"greek\">μισέω</span>.—B. 1132. DELG s.v. <span class=\"greek\">μισέω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μίτρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μίτρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Hom. e outros), faixa para o cabelo ou turbante usado como cobertura da cabeça (Pind., Hdt. e outros; Ex 29:6; Lev 8:9; Jdth l6:8; Bar 5:2; PsSol 2:21; TestLevi 8:2; EpArist 98; Philo, Mos. 2, 116) <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἦν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κατακάλυψις</span> <span class=\"greek\">αὐτῆς</span>, sua cobertura de cabeça era uma faixa Hv 4, 2, 1.—A <span class=\"greek\">μίτρα</span> também pode ter sido peça de vestuário usada desde a garganta ou a parte posterior do pescoço (Parthenius 11, 3 <span class=\"greek\">τὴν</span> <span class=\"greek\">μίτραν</span> <span class=\"greek\">ἐνθεῖναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span>). De todo modo, considerava-se que uma mulher não estava adequadamente coberta sem ela (Quint. Smyrn. 13, 110).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μιτυλήνη, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μιτυλήνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (grafia posterior [SIG 344, 30: 303 a.C.; OGI 266, 19: III a.C.; Strabo, Plut.; Jos., Ant. 15, 350; 16, 20] da forma mais antiga [Hdt., X., inscrições—Meisterhans3-Schw. p. 29] <span class=\"greek\">Μυτιλήνη</span>. Cf. B-D-F §42, 3; Mlt-H. 72; 79), Mitilene, cidade principal da ilha de Lesbos, no mar Egeu, diante da costa noroeste da Ásia Menor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:14</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μιχαήλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μιχαήλ</span>, <span class=\"greek\">ὁ</span>, indeclinável (<span class=\"hebrew\" dir=\"rtl\">מִיכָאֵל</span>), Miguel, arcanjo (Da 12:1; 10:13, 21; pseudoepígrafos; ISyriaW 2263; 2637b; inscrições da Ásia Menor [CB I/2, 541 n.º 404, p. 741 n.º 678]; PGM 1, 301; 2, 158; 3, 148; 4, 1815 e 2356; 7, 257; 22b, 29 <span class=\"greek\">τῷ</span> <span class=\"greek\">μεγάλῳ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">Ὀσίριδι</span> <span class=\"greek\">Μιχαήλ</span>) Jd 9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:7</a> (<span class=\"greek\">Μ</span>. como <span class=\"greek\">ἀρχιστρατηγός</span> PGM 13, 928. Sobre seu combate com o dragão, ver PGM 4, 2769ff); Hs 8, 3, 3. Na tradição israelita, <span class=\"greek\">Μ</span>. era o patrono e protetor especial de Israel (Da 12:1).—Bousset, Rel.3 325ff; Dssm., LO 396ff [LAE 456f]; WLueken, Der Erzengel M. 1898; JRohland, Der Erzengel M. ’77; RAC V 243–51; BHHW II 1212f.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνᾶ, μνᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνᾶ</span>, <span class=\"greek\">μνᾶς</span>, <span class=\"greek\">ἡ</span> (empréstimo semítico [cf. o acadiano Manû: A1 em CAD X 219], já em autores áticos; inscrições, papiros, LXX; Jos., Ant. 7, 189; 14, 106; TestJos 16:4), mina, unidade monetária grega = 100 dracmas (sobre o poder aquisitivo, ver <span class=\"greek\">δραχμή</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:13</a>, 16, 18, 20, 24f (sobre a parábola, ver PJoüon, RSR 29, ’40, 489–94).—Kl. Pauly III 1368f; BHHW II 1166–69. Bibliografia em <span class=\"greek\">ἀργύριον</span> 2c.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνάομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνάομαι</span> (de <span class=\"greek\">μιμνῄσκω</span> no sentido de “cortejar” [assim DELG e Frisk s.v. este último, e LfgrE s.v. <span class=\"greek\">μνάομαι</span>], mediante desenvolvimento especial do significado primário de <span class=\"greek\">μνάομαι</span>, “ter em mente”, que não aparece em nossa literatura; quanto a outras derivações, ver a bibliografia citada em Frisk II 240f e LfgrE III 232; cf. Hom. <span class=\"greek\">μνηστήρ</span>, “pretendente”; desde Hom., também Philo), cortejar, pretender tomar por esposa; particípio perfeito <span class=\"greek\">μεμνησμένη</span>, da mulher prometida em casamento, noiva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:27</a> D.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Μνάσων, ωνος, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Μνάσων</span>, <span class=\"greek\">ωνος</span>, <span class=\"greek\">ὁ</span> (Anth. Pal.; Lucian; GDI 2580, 25 [Delfos]; SIG 585: 43, 47, 77, 81, 85, 90, 94, 234, 238 [197 a.C.]; PHib 41, 3 [cerca de 261 a.C.]; Sb 3199), Mnasom, cristão de Chipre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:16</a> (<span class=\"greek\">Μνασέας</span>, pai de Zenão, o estoico, também era de Chipre; <span class=\"greek\">Κυπρ</span>. I p. 190 n.º 4, uma inscrição grega de Chipre contém o nome <span class=\"greek\">Μνασίας</span>. Em Just., D. 85, 6, um dos participantes do diálogo tem o nome <span class=\"greek\">Μνασέας</span>).—HCadbury, Amicitiae Corolla (para RHarris) ’33, 51–53; Hemer, Acts 237.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μνάομαι</span> no sentido de “ter em mente” [ver L-S-J-M <span class=\"greek\">μνάομαι</span> I]; Soph. e outros; inscrições, papiros, LXX, 8:5; OdeSol; Test Abr A 4 p. 81, 6 [Stone p. 10]; TestNapht 8:5; EpArist).</p><p class=\"entry-text\">① Lembrança, memória, com genitivo objetivo <span class=\"greek\">τινός</span>, de alguém (OdeSol 11:22; SibOr 5, 486) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:13</a>, variante de leitura; de alguma coisa (SIG 577, 3; Wsd 5:14; Bar 4:27) <span class=\"greek\">εἴ</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἀγαθοῦ</span> <span class=\"greek\">μ</span>., se há alguma lembrança do que é bom 21:7. <span class=\"greek\">μνείαν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τινός</span>, lembrar-se de alguém (Soph., El. 384 e outros) <span class=\"greek\">ἔχετε</span> <span class=\"greek\">μνείαν</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἀγαθὴν</span> <span class=\"greek\">πάντοτε</span>, sempre nos recordais com benevolência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:6</a>. <span class=\"greek\">ἀδιάλειπτον</span> <span class=\"greek\">ἔχω</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">μ</span>., recordo-me constantemente de ti <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:3</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἔρχεταί</span> <span class=\"greek\">τινι</span>, como no latim in mentem venit alicui, vem à memória de alguém Hv 3, 7, 3.</p><p class=\"entry-text\">② Menção, <span class=\"greek\">μνείαν</span> <span class=\"greek\">ποιεῖσθαί</span> <span class=\"greek\">τινος</span>, mencionar alguém (Pla., Phdr. 254; Diog. L. 8, 2, 66; IPriene 50, 10; PEdg 14 [=Sb 6720], 3 [256 a.C.]; UPZ 59, 6; cf. Ps 110:4); em nossa literatura, apenas acerca da menção em oração (BGU 632, 5 <span class=\"greek\">μνείαν</span> <span class=\"greek\">σου</span> <span class=\"greek\">ποιούμενος</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐνθάδε</span> <span class=\"greek\">θεοῖς</span>; Kaibel 983, 2ff [79 a.C.] <span class=\"greek\">Δημήτριος</span> <span class=\"greek\">ἥκω</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">μεγάλην</span> <span class=\"greek\">῏Ισιν</span> <span class=\"greek\">θεάν</span>, <span class=\"greek\">μνείαν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀγαθῷ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γονέων</span> <span class=\"greek\">ποιούμενος</span>; fora da oração Iren. 1, 9, 2 [Harv. I 83, 2]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:2</a>, variante de leitura; Phlm 4. O genitivo subentende-se pelo contexto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:2</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάση</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ὑμῶν</span>, sempre que faço menção de vós (em oração) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:3</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">μ</span>., menção (em oração) diante de Deus (embora também seja provável aqui “lembrança”) 1 Cl 56:1.—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 10. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνῆμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνῆμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">μνάομαι</span> [no sentido de “ter em mente, lembrar”], <span class=\"greek\">μιμνῄσκω</span>), literalmente um “sinal de lembrança”, especialmente dos mortos (Hom. e outros), depois, de maneira geral, sepultura, túmulo (Hdt., Pla. e outros; SIG 1221; 1237, 3; BGU 1024 IV, 23; LXX; TestSim 8:3; ParJer 9:32; Philo; Jos., Ant. 7, 19; 8, 240; Just., D. 10, 82 [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:13</a>]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:2</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:1</a> (<span class=\"greek\">μνημεῖον</span>, variante de leitura); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:29</a> (o <span class=\"greek\">μ</span>. de Davi, Jos., Ant. 7, 393); GPt 8:30–32; 11:44; 12:50, 52. <span class=\"greek\">κατατιθέναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>., depositar no túmulo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:46a</a>, variante de leitura; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:16</a>. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">λαξευτῷ</span>, depositar em sepultura escavada na rocha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:53</a>. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μνῆμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:9</a> (quanto à ideia, ver Jos., Bell. 4, 317). Morada de possessos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:3</a>, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:27</a>.—Sobre a função do <span class=\"greek\">μ</span>., ver SEG XL, n.º 1650 com referências.—M-M. TW.—Ver o artigo seguinte.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνημεῖον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνημεῖον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (ver <span class=\"greek\">μνήμα</span>), literalmente “sinal de lembrança” (Pind. e outros; Philo, Joseph.), especialmente dos mortos (Eur., Iph. T. 702; 821; Thu. 1, 138, 5; X., Hell. 2, 4, 17; 3, 2, 15; Pla., Rep. 3, 414a).</p><p class=\"entry-text\">① Monumento, memorial (cf. Jos., Ant. 5, 119 <span class=\"greek\">μν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τάφος</span>; HHäusle, Das Denkmal als Garant des Nachruhms [Zetemata 25] 1980 [inscrições; sobre a função de um monumento, ver pp. 29–40]): <span class=\"greek\">οἰκοδομεῖτε</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μνημεῖα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:47</a> (JJeremias, Heiligengräber in Jesu Umwelt ’58), provavelmente deve ser entendido nesse sentido (quanto a <span class=\"greek\">μ</span>. <span class=\"greek\">οἰκοδομεῖν</span>, cf. Jos., Ant. 13, 211). Mas <span class=\"greek\">μ</span>. em nossa literatura geralmente tem o sentido de</p><p class=\"entry-text\">② Sepultura, túmulo (SIG 1229, 4; 1232; 1234; 1242; 1244; PFlor 9, 10; Gen 23:6, 9; Is 22:16 e outros; TestSol 17:2; ParJer; ApcEsdr 4:36 p. 29, 14 Tdf.; ApcMos 42; AscIs 3:13; Jos., Ant. 1, 237; 18, 108; Mel., P. 78, 569; 90, 673); de sepulturas em cavernas etc. (ver PThomsen, Grab: Reallex. d. Vorgesch. IV 2, 473ff), nas quais se pode entrar (ver ParJer 7:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:6</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:29</a>; 27:52f (JBlinzler, ThGl 35, ’43, 91–93.—Diod S 13, 86, 3: quando os cartagineses, sitiando Acragas, destruíram algumas sepulturas fora dos muros, “durante toda a noite apareceram fantasmas dos mortos”, <span class=\"greek\">διὰ</span> <span class=\"greek\">νυκτὸς</span> <span class=\"greek\">εἴδωλα</span> <span class=\"greek\">φαίνεσθαι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τετελευτηκότων</span>.—Sobre um terremoto que abre os sepulcros e liberta os que estão dentro, ver Ps.-Ael. Aristid. 25, 20f K.=43 p. 804 D.: <span class=\"greek\">μνήματα</span> <span class=\"greek\">ἀνερρήγνυτο</span> … <span class=\"greek\">τὰ</span> <span class=\"greek\">μνήματα</span> <span class=\"greek\">ἀνερρίπτει</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">κειμένους</span>. EFascher, Die Auferweckung der Heiligen Mt 27:51–53, ’51), versículo 60b; 28:8; Mk 15:46ab; 16:2, 3, 5, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:55</a>; 24:1, variante de leitura, 2, 9, 12, 22, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:17</a>, 31 (Aesop, Fab. 109 H. [cf. 299 H-H.] <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἀπιοῦσα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μνημεῖον</span> <span class=\"greek\">ἐθρήνει</span>), 38; 12:17; 19:42; 20:1–4, 6, 8, 11ab; GPt 9:34; 12:51, 53 (bibliografia sobre o Santo Sepulcro: RGG3 II 1816–18; também FBraun, La Sépulture de Jésu ’37; RSmith, The Tomb of Jesus, BA 30, ’67, 74–90). <span class=\"greek\">τιθέναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., colocar no túmulo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:29</a>. Também <span class=\"greek\">τιθέναι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:60a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:29</a>; 15:46a. <span class=\"greek\">μ</span>. <span class=\"greek\">καινόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:60a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:41</a>; <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">μ</span>., os que estão em seus túmulos 5:28. Lugar frequentado por possessos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:2</a> (segundo Diog. L. 9, 38, Demócrito procurava solidão entre as sepulturas). Às vezes as sepulturas não eram reconhecíveis como tais pela aparência externa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:44</a>; ver <span class=\"greek\">ἄδηλος</span> 1.—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 5. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0237-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μνήμη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μνήμη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (trágicos+), primariamente “lembrança, memória”.</p><p class=\"entry-text\">① Recordação que alguém tem de acontecimentos, em oposição a ignorá-los por esquecimento, recordação, memória, com genitivo da coisa (EpArist 159; Just., D. 19, 6 e outros) <span class=\"greek\">τ</span>. <span class=\"greek\">μνήμην</span> <span class=\"greek\">τινὸς</span> <span class=\"greek\">ποιεῖσθαι</span>, trazer algo à memória <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:15</a> (PFay 19, 10 [11 d.C.] <span class=\"greek\">τῶν</span> <span class=\"greek\">πραγμάτων</span> <span class=\"greek\">μνήμην</span> <span class=\"greek\">ποιεῖσθαι</span> = “conservar os acontecimentos na lembrança”. Igualmente, escólio a Apollon. Rhod. 4, 839–41a.—O significado de <span class=\"greek\">μ</span>. <span class=\"greek\">ποιεῖσθαι</span>, atestado em Hdt. e outros; Jos., Ant. 18, 65 = “fazer menção”, dificilmente cabe aqui). <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προηθληκότων</span> <span class=\"greek\">μ</span>., em memória dos que já competiram MPol 18:2.</p><p class=\"entry-text\">② Estado de comemoração, recordação, memorial (Diod S 5, 73, 1 e 23, 15, 2 <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">μνήμην</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ἀνθρώποις</span>; testamento de Epicuro em Diog. L. 10, 18: refeição memorial <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">μνήμην</span>; <span class=\"greek\">ΕΛΛΗΝΙΚΑ</span> 1, 1928, p. 18, 18, festividades organizadas <span class=\"greek\">εἰς</span> <span class=\"greek\">μνήμην</span> <span class=\"greek\">Εὐρυκλέους</span> <span class=\"greek\">εὐεργέτου</span>; Jos., Ant. 13, 63); plural <span class=\"greek\">ἡ</span> <span class=\"greek\">τρυφὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπάτη</span> <span class=\"greek\">μνήμας</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχει</span> = não possuem lembrança = não são lembradas por muito tempo (como no latim memoriam non habet) Hs 6, 5, 3; <span class=\"greek\">μνήμας</span> <span class=\"greek\">μεγάλας</span> <span class=\"greek\">ἔχειν</span>, ter lembrança duradoura = permanecer muito tempo na memória, ibid. (cf. Proverbia Aesopi 111 P. <span class=\"greek\">μνήμην</span> <span class=\"greek\">ἔχειν</span>; EpArist 279).—DELG s.v. <span class=\"greek\">μιμνήσκω</span> 6. M-M. TW. Spicq. Sv.</p></section></article>"};
